     5→import { TableCell, TableRow } from "@/components/ui/table";
     6→import { Collapsible, CollapsibleContent, CollapsibleTrigger } from "@/components/ui/collapsible";
     7→import { Tooltip, TooltipContent, TooltipTrigger, TooltipProvider } from "@/components/ui/tooltip";
     8→import {
     9→  ChevronDown, ChevronUp, Phone, Mail, MapPin,
    10→  FileText, Archive
    11→} from "lucide-react";
    12→import { toast } from "sonner";
    13→import type { Result } from "@/pages/Index";
    14→import EmailOutreachDialog from "@/components/candidate/EmailOutreachDialog";
    15→
    16→// Sub-components
    17→import CandidateSummary from "@/components/candidate/CandidateSummary";
    18→import SkillsDetailPanel from "@/components/candidate/SkillsDetailPanel";
    19→import ExperiencePanel from "@/components/candidate/ExperiencePanel";
    20→import EducationPanel from "@/components/candidate/EducationPanel";
    21→import JDAlignedPanel from "@/components/candidate/JDAlignedPanel";
    22→import StrengthsGapsPanel from "@/components/candidate/StrengthsGapsPanel";
    23→import AINudgePanel from "@/components/candidate/AINudgePanel";
    24→import InterviewQuestionsPanel from "@/components/candidate/InterviewQuestionsPanel";
    25→import StageTracker from "@/components/candidate/StageTracker";
    26→import type { HiringStage } from "@/hooks/useStageTracker";
    27→
    28→interface CandidateRowProps {
    29→  result: Result;
    30→  index: number;
    31→  isExpanded: boolean;
    32→  isSelected: boolean;
    33→  jobTitle?: string | null;
    34→  onToggleRow: (id: string) => void;
    35→  onToggleSelect: (resumeId: string) => void;
    36→  onDownload: (filePath: string, filename: string) => void;
    37→  onDelete: (resumeId: string, filePath: string | null) => void;
    38→  onDismiss: (resumeId: string) => void;
    39→  formatCandidateName: (filename: string) => string;
    40→  currentStage?: HiringStage | null;
    41→  stageUpdatedAt?: string | null;
    42→  onStageChange?: (resumeId: string, stage: HiringStage) => void;
    43→  onRewriteJd?: () => void;
    44→}
    45→
    46→const getScoreColor = (score: number) => {
    47→  if (score >= 70) return "bg-score-skills";
    48→  if (score >= 40) return "bg-warning";
    49→  return "bg-destructive";
    50→};
    51→
    52→const getScoreTextColor = (score: number) => {
    53→  if (score >= 70) return "text-score-skills";
    54→  if (score >= 40) return "text-warning";
    55→  return "text-destructive";
    56→};
    57→
    58→const STAGE_BADGE_CLASSES: Record<string, string> = {
    59→  applied: "border-border bg-muted/50 text-muted-foreground",
    60→  screened: "border-blue-200 bg-blue-50 text-blue-700 dark:border-blue-700 dark:bg-blue-900/20 dark:text-blue-400",
    61→  interview: "border-purple-200 bg-purple-50 text-purple-700 dark:border-purple-700 dark:bg-purple-900/20 dark:text-purple-400",
    62→  offer: "border-amber-200 bg-amber-50 text-amber-700 dark:border-amber-700 dark:bg-amber-900/20 dark:text-amber-400",
    63→  hired: "border-emerald-200 bg-emerald-50 text-emerald-700 dark:border-emerald-700 dark:bg-emerald-900/20 dark:text-emerald-400",
    64→  rejected: "border-red-200 bg-red-50 text-red-700 dark:border-red-700 dark:bg-red-900/20 dark:text-red-400",
    65→};
    66→
    67→const getStrengthLabel = (score: number): { label: string; variant: "success" | "warning" | "destructive" } => {
    68→  if (score >= 70) return { label: "Strong", variant: "success" };
    69→  if (score >= 40) return { label: "Good", variant: "warning" };
    70→  return { label: "Weak", variant: "destructive" };
    71→};
    72→
    73→const getRankDisplay = (index: number) => {
    74→  if (index < 3) {
    75→    const colors = [
    76→      "bg-score-overall text-white",
    77→      "bg-muted-foreground/60 text-white",
    78→      "bg-warning text-white",
    79→    ];
    80→    return (
    81→      <span className={`inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-bold ${colors[index]}`}>
    82→        {index + 1}
    83→      </span>
    84→    );
    85→  }
    86→  return (
    87→    <span className="inline-flex items-center justify-center w-7 h-7 rounded-full text-xs font-medium bg-muted text-muted-foreground">
    88→      {index + 1}
    89→    </span>
    90→  );
    91→};
    92→
    93→const CandidateRow = ({
    94→  result: r,
    95→  index,
    96→  isExpanded,
    97→  isSelected,
    98→  jobTitle,
    99→  onToggleRow,
   100→  onToggleSelect,
   101→  onDownload,
   102→  onDelete,
   103→  onDismiss,
   104→  formatCandidateName,
   105→  currentStage,
   106→  stageUpdatedAt,
   107→  onStageChange,
   108→  onRewriteJd,
   109→}: CandidateRowProps) => {
   110→  const [emailDialogOpen, setEmailDialogOpen] = useState(false);
   111→  const strength = !r.pending ? getStrengthLabel(r.overall_score) : null;
   112→
   113→  return (
   114→    <>
   115→    <Collapsible open={isExpanded} onOpenChange={() => onToggleRow(r.id)} asChild>
   116→      <>
   117→        {/* Collapsed Row */}
   118→        <TableRow className="cursor-pointer hover:bg-muted/50 transition-colors" onClick={() => !r.pending && onToggleRow(r.id)}>
   119→          <TableCell onClick={(e) => e.stopPropagation()}>
   120→            <Checkbox checked={isSelected} onCheckedChange={() => onToggleSelect(r.resume_id)} />
   121→          </TableCell>
   122→          <TableCell className="text-center">
   123→            {r.pending ? <span className="text-sm text-muted-foreground">—</span> : getRankDisplay(index)}
   124→          </TableCell>
   125→          <TableCell className="font-medium">
   126→            <div className="flex flex-col gap-0.5">
   127→              <span className="text-sm">{r.candidate_name || formatCandidateName(r.filename)}</span>
   128→              {r.candidate_location && (
   129→                <span className="flex items-center gap-1 text-xs text-muted-foreground">
   130→                  <MapPin className="h-3 w-3" /> {r.candidate_location}
   131→                </span>
   132→              )}
   133→              {!r.pending && currentStage && currentStage !== "applied" && (
   134→                <Badge
   135→                  variant="outline"
   136→                  className={`w-fit text-[10px] capitalize border ${STAGE_BADGE_CLASSES[currentStage] ?? ""}`}
   137→                >
   138→                  {currentStage}
   139→                </Badge>
   140→              )}
   141→            </div>
   142→          </TableCell>
   143→          <TableCell>
   144→            {r.pending ? (
   145→              <Badge variant="outline" className="text-xs">Pending</Badge>
   146→            ) : (
   147→              <div className="flex items-center gap-2">
   148→                <div className="flex-1 h-2 rounded-full bg-secondary overflow-hidden max-w-[100px]">
   149→                  <div
   150→                    className={`h-full rounded-full transition-all ${getScoreColor(r.overall_score)}`}
   151→                    style={{ width: `${Math.min(r.overall_score, 100)}%` }}
   152→                  />
   153→                </div>
   154→                <span className={`text-sm font-semibold tabular-nums min-w-[3ch] ${getScoreTextColor(r.overall_score)}`}>
   155→                  {r.overall_score?.toFixed(0)}%
   156→                </span>
   157→              </div>
   158→            )}
   159→          </TableCell>
   160→          <TableCell>
   161→            <div className="flex flex-wrap items-center gap-1">
   162→              {!r.pending && strength && (
   163→                <Badge variant={strength.variant} className="text-[10px]">
   164→                  {strength.label}
   165→                </Badge>
   166→              )}
   167→              {!r.pending && r.scoring_version === "heuristic" && (
   168→                <TooltipProvider delayDuration={300}>
   169→                  <Tooltip>
   170→                    <TooltipTrigger asChild>
   171→                      <span className="inline-flex items-center text-[10px] px-1.5 py-0.5 rounded bg-muted text-muted-foreground font-medium cursor-default">
   172→                        Quick
   173→                      </span>
   174→                    </TooltipTrigger>
   175→                    <TooltipContent className="max-w-xs text-xs">
   176→                      This candidate was ranked by keyword matching. Top 20 candidates receive full AI scoring.
   177→                    </TooltipContent>
   178→                  </Tooltip>
   179→                </TooltipProvider>
   180→              )}
   181→            </div>
   182→          </TableCell>
   183→          <TableCell>
   184→            <div className="flex items-center gap-0.5" onClick={(e) => e.stopPropagation()}>
   185→              <TooltipProvider delayDuration={300}>
   186→                {/* Phone */}
   187→                <Tooltip>
   188→                  <TooltipTrigger asChild>
   189→                    {r.candidate_phone ? (
   190→                      <a
   191→                        href={`tel:${r.candidate_phone}`}
   192→                        onClick={(e) => {
   193→                          if (!/Mobi|Android/i.test(navigator.userAgent)) {
   194→                            e.preventDefault();
   195→                            navigator.clipboard.writeText(r.candidate_phone!);
   196→                            toast.success("Phone number copied!");
   197→                          }
   198→                        }}
   199→                      >
   200→                        <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary">
   201→                          <Phone className="h-3.5 w-3.5" />
   202→                        </Button>
   203→                      </a>
   204→                    ) : (
   205→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
   206→                        <Phone className="h-3.5 w-3.5" />
   207→                      </Button>
   208→                    )}
   209→                  </TooltipTrigger>
   210→                  <TooltipContent>{r.candidate_phone ? `Copy: ${r.candidate_phone}` : "Phone not found in resume"}</TooltipContent>
   211→                </Tooltip>
   212→
   213→                {/* Email */}
   214→                <Tooltip>
   215→                  <TooltipTrigger asChild>
   216→                    {r.candidate_email ? (
   217→                      <Button
   218→                        variant="ghost"
   219→                        size="icon"
   220→                        className="h-7 w-7 text-muted-foreground hover:text-primary"
   221→                        onClick={() => setEmailDialogOpen(true)}
   222→                      >
   223→                        <Mail className="h-3.5 w-3.5" />
   224→                      </Button>
   225→                    ) : (
   226→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
   227→                        <Mail className="h-3.5 w-3.5" />
   228→                      </Button>
   229→                    )}
   230→                  </TooltipTrigger>
   231→                  <TooltipContent>{r.candidate_email ? `Email: ${r.candidate_email}` : "Email not found in resume"}</TooltipContent>
   232→                </Tooltip>
   233→
   234→                {/* Download */}
   235→                <Tooltip>
   236→                  <TooltipTrigger asChild>
   237→                    {r.file_path ? (
   238→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground hover:text-primary" onClick={() => onDownload(r.file_path!, r.filename)}>
   239→                        <FileText className="h-3.5 w-3.5" />
   240→                      </Button>
   241→                    ) : (
   242→                      <Button variant="ghost" size="icon" className="h-7 w-7 text-muted-foreground/30 cursor-default" disabled>
   243→                        <FileText className="h-3.5 w-3.5" />
   244→                      </Button>
   245→                    )}
   246→                  </TooltipTrigger>
   247→                  <TooltipContent>{r.file_path ? "Download resume" : "No file"}</TooltipContent>
   248→                </Tooltip>
   249→
   250→                {/* Archive */}
   251→                <Tooltip>
   252→                  <TooltipTrigger asChild>
   253→                    <Button
   254→                      variant="ghost" size="icon"
   255→                      className="h-7 w-7 text-muted-foreground hover:text-amber-500"
   256→                      onClick={() => onDismiss(r.resume_id)}
   257→                    >
   258→                      <Archive className="h-3.5 w-3.5" />
   259→                    </Button>
   260→                  </TooltipTrigger>
   261→                  <TooltipContent>Archive candidate</TooltipContent>
   262→                </Tooltip>
   263→              </TooltipProvider>
   264→
   265→              {!r.pending && (
   266→                <CollapsibleTrigger asChild>
   267→                  <Button variant="ghost" size="icon" className="h-7 w-7">
   268→                    {isExpanded ? <ChevronUp className="h-4 w-4" /> : <ChevronDown className="h-4 w-4" />}
   269→                  </Button>
   270→                </CollapsibleTrigger>
   271→              )}
   272→            </div>
   273→          </TableCell>
   274→        </TableRow>
   275→
   276→        {/* Expanded Detail — New Layout */}
   277→        {!r.pending && (
   278→          <CollapsibleContent asChild>
   279→            <TableRow className="bg-muted/30 hover:bg-muted/30">
   280→              <TableCell colSpan={6} className="p-5">
   281→                <div className="space-y-4">
   282→                  {/* 1. Summary + Stage Tracker — unified overview card */}
   283→                  {(() => {
   284→                    const hasSummary = !!(r.explanation_json?.summary || r.summary);
   285→                    if (!hasSummary && !onStageChange) return null;
   286→                    return (
   287→                      <div className="rounded-lg border bg-background overflow-hidden">
   288→                        {hasSummary && (
   289→                          <div className="px-4 py-3">
   290→                            <CandidateSummary result={r} />
   291→                          </div>
   292→                        )}
   293→                        {onStageChange && (
   294→                          <div className={`px-4 py-3${hasSummary ? " border-t bg-muted/40" : ""}`}>
   295→                            <StageTracker
   296→                              currentStage={currentStage || "applied"}
   297→                              updatedAt={stageUpdatedAt}
   298→                              onStageChange={(stage) => onStageChange(r.resume_id, stage)}
   299→                            />
   300→                          </div>
   301→                        )}
   302→                      </div>
   303→                    );
   304→                  })()}
   305→
   306→                  {/* 2. Strengths & Gaps — high signal, show first */}
   307→                  <StrengthsGapsPanel result={r} />
   308→
   309→                  {/* 3. Skills Detail | Experience | Education — 3 columns */}
   310→                  <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
   311→                    <SkillsDetailPanel result={r} />
   312→                    <ExperiencePanel parsedJson={r.parsed_json} />
   313→                    <EducationPanel parsedJson={r.parsed_json} matchedMustHaves={r.matched_must_haves} missingMustHaves={r.missing_must_haves} />
   314→                  </div>
   315→
   316→                  {/* 4. JD Aligned — full width */}
   317→                  <JDAlignedPanel result={r} />
   318→
   319→                  {/* 6. AI Nudge + Rewrite JD */}
   320→                  <AINudgePanel result={r} onRewriteJd={onRewriteJd} />
   321→
   322→                  {/* 7. Interview Questions — collapsible */}
   323→                  <InterviewQuestionsPanel result={r} />
   324→                </div>
   325→              </TableCell>
   326→            </TableRow>
   327→          </CollapsibleContent>
   328→        )}
   329→      </>
   330→    </Collapsible>
   331→
   332→    {r.candidate_email && (
   333→      <EmailOutreachDialog
   334→        open={emailDialogOpen}
   335→        onOpenChange={setEmailDialogOpen}
   336→        candidateName={r.candidate_name || r.filename}
   337→        candidateEmail={r.candidate_email}
   338→        jobTitle={jobTitle || "Open Position"}
   339→        matchScore={Math.round(r.overall_score ?? 0)}
   340→        resumeId={r.resume_id}
   341→        jobId={r.id}
   342→      />
   343→    )}
   344→    </>
   345→  );
   346→};
   347→
   348→export default CandidateRow;
   349→

